from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        byb = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = min(x, y), max(x, y)
            byb[b].append((a, i))
        delta = [0] * m
        S = 0
        v1, i1, v2 = 0, -1, 0
        for r in range(1, n + 1):
            for a, i in byb[r]:
                if a > v1:
                    v2 = v1
                    v1, i1 = a, i
                elif a > v2:
                    v2 = a
            S += r - v1
            if i1 >= 0:
                delta[i1] += v1 - v2
        return S + max(delta)

