import sys
import numpy as np
def solve(data):
    it=iter(data)
    n=int(next(it)); m=int(next(it)); q=int(next(it))
    E=[]
    for _ in range(m):
        a=int(next(it))-1; b=int(next(it))-1; c=int(next(it)); E.append((a,b,c))
    Qs=[]
    closed=[False]*m
    for _ in range(q):
        t=next(it)
        if t=='1':
            i=int(next(it))-1; closed[i]=True; Qs.append((1,i,0))
        else:
            x=int(next(it))-1; y=int(next(it))-1; Qs.append((2,x,y))
    INF=10**15
    d=np.full((n,n),INF,dtype=np.int64)
    np.fill_diagonal(d,0)
    for i in range(m):
        if not closed[i]:
            a,b,c=E[i]
            if c<d[a,b]: d[a,b]=c; d[b,a]=c
    for k in range(n):
        d=np.minimum(d, d[:,k:k+1]+d[k:k+1,:])
        np.minimum(d,INF,out=d)
    ans=[]
    for t,x,y in reversed(Qs):
        if t==2:
            v=int(d[x,y])
            ans.append(-1 if v>=INF else v)
        else:
            a,b,c=E[x]
            col_a=d[:,a:a+1].copy(); col_b=d[:,b:b+1].copy()
            row_a=d[a:a+1,:].copy(); row_b=d[b:b+1,:].copy()
            d=np.minimum(d, np.minimum(col_a+c+row_b, col_b+c+row_a))
            np.minimum(d,INF,out=d)
    return "\n".join(map(str,reversed(ans)))
