class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        N = L + 1
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for i in range(N + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD
        # f[c]: number of operations to reach 1 starting from c
        f = [0] * (N + 1)
        for c in range(2, N + 1):
            f[c] = 1 + f[bin(c).count('1')]
        S = [c for c in range(1, N + 1) if f[c] <= k - 1]
        # cnt[c] = number of x in [0, n) with popcount c
        cnt = [0] * (N + 1)
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                r = L - i - 1
                # free bits r, need c - ones set bits among them
                for c in S:
                    j = c - ones
                    if 0 <= j <= r:
                        cnt[c] = (cnt[c] + C[r][j]) % MOD
                ones += 1
        ans = 0
        for c in S:
            ans += cnt[c]
        return ans % MOD

