def ok(ivs,n,V):
    for P in itertools.product(range(V),repeat=n):
        good=True
        for a,b,t in ivs:
            c=P[a]
            if P[b]!=c: good=False;break
            for x in range(a+1,b):
                if (t==1 and not P[x]>c) or (t==0 and not P[x]<c): good=False;break
            if not good: break
        if good: return True
    return False
