def main():
    d = sys.stdin.read().split()
    H, W, X = int(d[0]), int(d[1]), int(d[2])
    P, Q = int(d[3]) - 1, int(d[4]) - 1
    S = [int(v) for v in d[5:5 + H * W]]
    cur = S[P * W + Q]
    seen = [False] * (H * W)
    start = P * W + Q
    seen[start] = True
    heap = []
    def push(r, c):
        idx = r * W + c
        if not seen[idx]:
            seen[idx] = True
            heapq.heappush(heap, (S[idx], r, c))
    def nb(r, c):
        if r > 0: push(r - 1, c)
        if r < H - 1: push(r + 1, c)
        if c > 0: push(r, c - 1)
        if c < W - 1: push(r, c + 1)
