from collections import defaultdict

def solve(A, D=100):
    states = {0: 0, 1: 0}
    ans = -1
    for d in range(1, D):
        M1 = 1 << (d - 1)
        M = 1 << d
        bucket = defaultdict(list)
        for a in A:
            bucket[a % M1].append(a)
        new = {}
        for r, V in states.items():
            L = bucket.get((-r) % M1)
            if not L:
                if V > ans:
                    ans = V
                continue
            for e in (0, 1):
                r2 = r + e * M
                g = 0
                for a in L:
                    x = r2 + a
                    if x % M == M1:
                        g += (x >> d) & 1
                val = V + g
                if val > new.get(r2, -1):
                    new[r2] = val
        states = new
    for r, V in states.items():
        if r == 0:
            continue
        if V > ans:
            ans = V
    return ans

