from collections import deque

def solve(N, M, A, B):
    s = []
    for i in range(N-1):
        d0 = A[i]-A[i+1]
        r = (B[i]-B[i+1]) % M
        f = r if d0 > 0 else r - M
        s.append(f - d0)
    p = [0]*N
    for i in range(1, N):
        p[i] = p[i-1] + s[i-1]
    # x_i = t - p_i, need t ≡ B_1-A_1 mod M
    r = (B[0]-A[0]) % M
    med = sorted(p)[N//2]
    t1 = med - ((med - r) % M)
    best = None
    for t in (t1-M, t1, t1+M, t1+2*M):
        c = sum(abs(t-x) for x in p)
        if best is None or c < best:
            best = c
    return best

def brute(N, M, A, B):
    A = tuple(A); B = tuple(B)
    dist = {A: 0}
    q = deque([A])
    while q:
        cur = q.popleft()
        if cur == B:
            return dist[cur]
        for i in range(N):
            for d in (1, -1):
                nv = (cur[i]+d) % M
                if N > 1:
                    if i > 0 and cur[i-1] == nv: continue
                    if i < N-1 and cur[i+1] == nv: continue
                nxt = cur[:i]+(nv,)+cur[i+1:]
                if nxt not in dist:
                    dist[nxt] = dist[cur]+1
                    q.append(nxt)
    return -1

