import random,itertools
def fast(a):
    n=len(a);h=n//2;i=0
    for j in range(h,n):
        if i<h and 2*a[i]<=a[j]: i+=1
    return i
def brute(a):
    n=len(a);best=0
    def rec(avail,k):
        nonlocal best
        best=max(best,k)
        l=list(avail)
        for x,y in itertools.combinations(range(len(l)),2):
            p,q=l[x],l[y]
            rest=[l[t] for t in range(len(l)) if t not in(x,y)]
            if 2*p<=q: rec(rest,k+1)
            if 2*q<=p: rec(rest,k+1)
    rec(a,0)
    return best
for _ in range(300):
    n=random.randint(2,7)
    a=sorted(random.randint(1,20) for _ in range(n))
    assert fast(a)==brute(a),a
print("ok")

