from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        Fs = []; Hs = []
        for dr, dc in dirs:
            F = [[0]*m for _ in range(n)]
            rows = range(n) if dr == 1 else range(n-1, -1, -1)
            for i in rows:
                gi = grid[i]; Fi = F[i]
                for j in range(m):
                    v = gi[j]
                    if v == 1:
                        Fi[j] = 1
                    elif v == 2 or v == 0:
                        pi = i - dr; pj = j - dc
                        if 0 <= pi < n and 0 <= pj < m and F[pi][pj] > 0:
                            pv = grid[pi][pj]
                            if (v == 2 and pv != 2) or (v == 0 and pv == 2):
                                Fi[j] = F[pi][pj] + 1
            Fs.append(F)
            H = [[0]*m for _ in range(n)]
            rows2 = range(n-1, -1, -1) if dr == 1 else range(n)
            for i in rows2:
                gi = grid[i]; Hi = H[i]
                for j in range(m):
                    v = gi[j]
                    if v == 2 or v == 0:
                        si = i + dr; sj = j + dc
                        if 0 <= si < n and 0 <= sj < m and grid[si][sj] == (0 if v == 2 else 2):
                            Hi[j] = 1 + H[si][sj]
                        else:
                            Hi[j] = 1
            Hs.append(H)
        ans = 0
        for k in range(4):
            F = Fs[k]
            kn = (k + 1) % 4
            dr, dc = dirs[kn]
            H = Hs[kn]
            for i in range(n):
                for j in range(m):
                    f = F[i][j]
                    if f == 0:
                        continue
                    if f > ans:
                        ans = f
                    v = grid[i][j]
                    need = 2 if v != 2 else 0
                    xi = i + dr; xj = j + dc
                    if 0 <= xi < n and 0 <= xj < m and grid[xi][xj] == need:
                        t = f + H[xi][xj]
                        if t > ans:
                            ans = t
        return ans

