from math import factorial
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def feas(o, e, nxt_odd):
            if o + e == 0:
                return True
            if nxt_odd:
                return o - e in (0, 1)
            return e - o in (0, 1)

        def count_after(o, e, x_odd):
            if x_odd:
                o -= 1
            else:
                e -= 1
            if o < 0 or e < 0:
                return 0
            if not feas(o, e, not x_odd):
                return 0
            return factorial(o) * factorial(e)

        O = (n + 1) // 2
        E = n // 2
        total = 0
        for x in range(1, n + 1):
            total += count_after(O, E, x % 2 == 1)
        if k > total:
            return []

        remaining = list(range(1, n + 1))
        o, e = O, E
        res = []
        prev_odd = None
        for _ in range(n):
            chosen = None
            for x in remaining:
                xo = (x % 2 == 1)
                if prev_odd is not None and xo == prev_odd:
                    continue
                c = count_after(o, e, xo)
                if k <= c:
                    chosen = x
                    break
                k -= c
            remaining.remove(chosen)
            res.append(chosen)
            if chosen % 2 == 1:
                o -= 1
            else:
                e -= 1
            prev_odd = (chosen % 2 == 1)
        return res

