class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2
        ws = []
        for i in range(half):
            j = n - 1 - i
            if i == j:
                ws.append(pow(10, i, k))
            else:
                ws.append((pow(10, i, k) + pow(10, j, k)) % k)
        reach = [None] * (half + 1)
        reach[half] = frozenset([0])
        for i in range(half - 1, -1, -1):
            w = ws[i]
            digs = range(1, 10) if i == 0 else range(10)
            nxt = reach[i + 1]
            reach[i] = frozenset((d * w + s) % k for d in digs for s in nxt)
        if 0 not in reach[0]:
            return "-1"
        cur = 0
        out = []
        for i in range(half):
            w = ws[i]
            digs = range(9, 0, -1) if i == 0 else range(9, -1, -1)
            nxt = reach[i + 1]
            for d in digs:
                r = (cur + d * w) % k
                if (-r) % k in nxt:
                    out.append(str(d))
                    cur = r
                    break
        s = "".join(out)
        return s + s[:n // 2][::-1]

