class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        M = max(cnt)
        INF = float('inf')

        def LB(f):
            return min(abs(n - k * f) for k in range(0, 27))

        cands = sorted(range(1, M + 2), key=LB)
        best = n
        for f in cands:
            if LB(f) >= best:
                break
            K = f
            dp = [INF] * (K + 1)
            dp[0] = 0
            for i in range(26):
                c = cnt[i]
                ndp = [INF] * (K + 1)
                bestA = [INF] * (K + 1)
                for k in range(K + 1):
                    d = dp[k]
                    if d == INF:
                        continue
                    a = c + k
                    if a >= f:
                        L = min(a - f, K)
                        v = d + a - f
                        if v < bestA[L]:
                            bestA[L] = v
                    else:
                        v = d + f - a
                        if v < ndp[0]:
                            ndp[0] = v
                    L = min(a, K)
                    v = d + a
                    if v < bestA[L]:
                        bestA[L] = v
                if i == 25:
                    for L in range(K + 1):
                        if bestA[L] < ndp[0]:
                            ndp[0] = bestA[L]
                    dp = ndp
                    break
                run = INF
                for L in range(K, -1, -1):
                    if bestA[L] < run:
                        run = bestA[L]
                    if run < ndp[L]:
                        ndp[L] = run
                dp = ndp
            if dp[0] < best:
                best = dp[0]
        return int(best)

