def fast(n,s):
    # c[p] = sum over j (1-indexed) with N-j >= p of d_j*j
    # prefix over j: P[k] = sum_{j<=k} d_j*j ; c[p] = P[N-p]
    P=[0]*(n+1)
    acc=0
    for j in range(1,n+1):
        acc+=(ord(s[j-1])-48)*j
        P[j]=acc
    digs=[]
    carry=0
    for p in range(n+1):
        v=P[n-p]+carry if n-p>=0 else carry
        digs.append(v%10)
        carry=v//10
    while carry:
        digs.append(carry%10); carry//=10
    while len(digs)>1 and digs[-1]==0: digs.pop()
    return int(''.join(map(str,reversed(digs))))
