class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)
        def find_all(pat):
            if pat == "":
                return list(range(n + 1))
            m = len(pat)
            f = [0] * m
            k = 0
            for q in range(1, m):
                while k and pat[q] != pat[k]:
                    k = f[k - 1]
                if pat[q] == pat[k]:
                    k += 1
                f[q] = k
            res = []
            k = 0
            for i, ch in enumerate(s):
                while k and ch != pat[k]:
                    k = f[k - 1]
                if ch == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = f[k - 1]
            return res
        pa = find_all(A)
        pb = find_all(B)
        pc = find_all(C)
        if not pa or not pb or not pc:
            return -1
        la, lb, lc = len(A), len(B), len(C)
        best = -1
        for i in pa:
            j_idx = bisect.bisect_left(pb, i + la)
            if j_idx == len(pb):
                continue
            j = pb[j_idx]
            k_idx = bisect.bisect_left(pc, j + lb)
            if k_idx == len(pc):
                continue
            k = pc[k_idx]
            cand = k + lc - i
            if best == -1 or cand < best:
                best = cand
        return best

