import itertools, numpy as np
from fractions import Fraction
def solve(N,M):
    # states: (c tuple len N, pos) pos=-1 root, else branch i depth d encoded as (i,d)
    idx={}; states=[]
    for c in itertools.product(range(M+1),repeat=N):
        for pos in [(-1,0)]+[(i,d) for i in range(N) for d in range(1,M+1) if d<=c[i]]:
            idx[(c,pos)]=len(states); states.append((c,pos))
    n=len(states)
    A=np.eye(n); b=np.zeros(n)
    for s,(c,pos) in enumerate(states):
        if all(x==M for x in c): continue
        b[s]=1
        moves=[]
        if pos==(-1,0):
            for i in range(N): moves.append((i,1))
        else:
            i,d=pos
            moves.append((i,d-1) if d-1>0 else (-1,0))
            if d<M: moves.append((i,d+1))
        p=1.0/len(moves)
        for (i,d) in moves:
            cc=list(c)
            if i>=0: cc[i]=max(cc[i],d)
            t=idx[(tuple(cc),(i,d) if i>=0 else (-1,0))]
            A[s,t]-=p
    # terminal states: rows identity with b=0 ok
    x=np.linalg.solve(A,b)
    return x[idx[((0,)*N,(-1,0))]]
for N in range(1,4):
    for M in range(1,6):
        if (M+1)**N*(N*M+1)>3000: continue
        v=solve(N,M)
        print(N,M,round(v,6),Fraction(v).limit_denominator(100000))

