import sys, random
def main():
    data = sys.stdin.read().split()
    K = int(data[0]); S = data[1]; T = data[2]
    n, m = len(S), len(T)
    if abs(m - n) > K:
        print("No"); return
    MOD = (1 << 61) - 1
    B = random.randrange(10**6, MOD - 10**6)
    HS = [0] * (n + 1)
    h = 0
    for idx, c in enumerate(S.encode()):
        h = (h * B + c) % MOD
        HS[idx + 1] = h
    HT = [0] * (m + 1)
    h = 0
    for idx, c in enumerate(T.encode()):
        h = (h * B + c) % MOD
        HT[idx + 1] = h
    maxlen = max(n, m) + 1
    P = [1] * (maxlen + 1)
    for x in range(1, maxlen + 1):
        P[x] = P[x - 1] * B % MOD

    def slide(i, j):
        if i >= n or j >= m or S[i] != T[j]:
            return i
        hi = min(n - i, m - j)
        lo = 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            a = (HS[i + mid] - HS[i] * P[mid]) % MOD
            b = (HT[j + mid] - HT[j] * P[mid]) % MOD
            if a == b:
                lo = mid
            else:
                hi = mid - 1
        return i + lo

    target = m - n
    prev = {0: slide(0, 0)}
    if prev.get(target) == n:
        print("Yes"); return
    for e in range(1, K + 1):
        cur = {}
        for d in range(-e, e + 1):
            best = None
            cands = []
            if d in prev:
                cands.append(prev[d] + 1)
            if d - 1 in prev:
                cands.append(prev[d - 1])
            if d + 1 in prev:
                cands.append(prev[d + 1] + 1)
            for i in cands:
                if 0 <= i <= n and 0 <= i + d <= m:
                    if best is None or i > best:
                        best = i
            if best is not None:
                cur[d] = slide(best, best + d)
        if cur.get(target) == n:
            print("Yes"); return
        prev = cur
    print("No")
main()

