        INF = float('inf')
        minp = [INF] * k
        minp[0] = 0
        P = 0
        ans = -INF
        for j in range(1, len(nums) + 1):
            P += nums[j - 1]
            r = j % k
            if minp[r] != INF:
                v = P - minp[r]
                if v > ans:
                    ans = v
            if P < minp[r]:
                minp[r] = P
        return int(ans)

