def brute(n,edges):
    # shortest cycle through 1 via BFS over all paths: dist from 1 to each vertex, check edge into 1
    adj=[[] for _ in range(n+1)]
    for a,b in edges: adj[a].append(b)
    best=-1
    # Floyd-ish: BFS from 1 with dist; cycle length = min over u->1 of d(u)+1
    d={1:0};q=deque([1])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if v not in d: d[v]=d[u]+1;q.append(v)
    for a,b in edges:
        if b==1 and a in d:
            c=d[a]+1
            best=c if best<0 else min(best,c)
    return best
