class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        # If S is the sum element and O the outlier, total T = 2S + O, so O = T - 2S.
        cnt = Counter(nums)
        T = sum(nums)
        ans = None
        for x in cnt:
            o = T - 2 * x
            if o in cnt and (o != x or cnt[x] >= 2):
                if ans is None or o > ans:
                    ans = o
        return ans

