from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        MASK = (1 << 1001) - 1

        def ok(reach):
            for j in range(n):
                if not (reach[j] >> nums[j]) & 1:
                    return False
            return True

        reach = [1] * n
        if ok(reach):
            return 0
        for k, (l, r, v) in enumerate(queries):
            for j in range(l, r + 1):
                reach[j] = (reach[j] | (reach[j] << v)) & MASK
            if ok(reach):
                return k + 1
        return -1

