import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        is_p = [False, False] + [True] * (N - 2)
        i = 2
        while i * i < N:
            if is_p[i]:
                for j in range(i * i, N, i):
                    is_p[j] = False
            i += 1
        if is_p[n] or is_p[m]:
            return -1
        L = len(str(n))
        pows = [10 ** i for i in range(L)]
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d != dist.get(u):
                continue
            if u == m:
                return d
            for p in pows:
                dig = (u // p) % 10
                if dig < 9:
                    v = u + p
                    if not is_p[v]:
                        nd = d + v
                        if nd < dist.get(v, float('inf')):
                            dist[v] = nd
                            heapq.heappush(pq, (nd, v))
                if dig > 0:
                    v = u - p
                    if not is_p[v]:
                        nd = d + v
                        if nd < dist.get(v, float('inf')):
                            dist[v] = nd
                            heapq.heappush(pq, (nd, v))
        return -1

