import operator
from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        a = nums; n = len(a)
        if n < 3:
            return 0
        # Z-function: z[i] = lcp(a, a[i:])
        z = [0]*n; z[0] = n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r-i, z[i-l])
            while i+z[i] < n and a[z[i]] == a[i+z[i]]:
                z[i] += 1
            if i+z[i] > r:
                l, r = i, i+z[i]
        total = 0
        ge = operator.ge
        R = []  # R[k] = lcp(i, i+1+k)
        for i in range(n-2, 0, -1):
            ai = a[i]
            R = [p+1 if x == ai else 0 for x, p in zip(a[i+1:], R+[0])]
            # Condition B: nums2 is prefix of nums3, j = i+1+k, need lcp(i,j) >= j-i
            total += sum(map(ge, R, range(1, n-i)))
            # Condition A: nums1 prefix of nums2 (j >= 2i); subtract overlap with B
            if z[i] >= i and 2*i <= n-1:
                total += (n-2*i) - sum(map(ge, R[i-1:], range(i, n-i)))
        return total

