from typing import List
class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        NEG = -10**9
        f = [NEG] * (m + 1)
        f[0] = 0
        tgt = [False] * len(source)
        for t in targetIndices:
            tgt[t] = True
        for i, c in enumerate(source):
            t = tgt[i]
            for j in range(m, -1, -1):
                old = f[j]
                if old == NEG:
                    continue
                if j < m and pattern[j] == c and old > f[j + 1]:
                    f[j + 1] = old
                if t:
                    f[j] = old + 1
        return max(f[m], 0)

