from typing import List
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            radj[b].append((a, w))
        INF = float('inf')
        d = [INF] * n
        d[0] = 0
        pq = [(0, 0)]
        while pq:
            c, u = heapq.heappop(pq)
            if c > d[u]:
                continue
            for v, w in radj[u]:
                nc = c if c > w else w
                if nc < d[v]:
                    d[v] = nc
                    heapq.heappush(pq, (nc, v))
        if any(x == INF for x in d):
            return -1
        return max(d)

