class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = {}
        for a, b in states:
            dp[(a, b)] = cost[0][a] + cost[n-1][b]
        for i in range(1, n // 2):
            j = n - 1 - i
            nd = {}
            for a, b in states:
                best = INF
                for (pa, pb), v in dp.items():
                    if pa != a and pb != b and v < best:
                        best = v
                nd[(a, b)] = best + cost[i][a] + cost[j][b]
            dp = nd
