class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vmap = {'a':1,'e':2,'i':4,'o':8,'u':16}
        n = len(word)
        full = 31
        total = 0
        for i in range(n):
            mask = 0
            cons = 0
            for j in range(i, n):
                c = word[j]
                if c in vmap:
                    mask |= vmap[c]
                else:
                    cons += 1
                    if cons > k:
                        break
                if mask == full and cons == k:
                    total += 1
        return total

